SELECT (CASE WHEN (CAST(wins_4.nfin AS BIGINT) = 1) THEN 'Yes' ELSE 'No' END) AS calculation__1136595897793773568,   CAST(wins_4.nfpsx AS BIGINT) AS nfpsx,   SUM(CAST(wins_4.number_of_records AS BIGINT)) AS sum_number_of_records_ok FROM wins_4 WHERE ((wins_4.ttrk3 NOT IN ('MD', 'RET', 'PLN', 'ONE', 'BCF', 'WRD', 'HST', 'HPO', 'PRV', 'ASD', 'CLS', 'FAR', 'TIL', 'GPR', 'ELK', 'ARP', 'SWF', 'EMD', 'CAS', 'CBY', 'SDY', 'ZIA', 'CWF', 'RIL', 'RP', 'BKF', 'FON', 'ALB', 'FER', 'SRP', 'RUI', 'DEP', 'ELY', 'GF', 'EMT', 'GIL', 'MED', 'ABT', 'PHA', 'BOI', 'OTC', 'UN', 'LNN', 'SUD', 'LBG', 'WYO', 'SON', 'MIL', 'FTP', 'GRP', 'FMT', 'CPW')) AND (wins_4.ttrk3 >= 'AP') AND (wins_4.ttrk3 <= 'WO')) GROUP BY calculation__1136595897793773568,   wins_4.nfpsx,   wins_4.nfpsx;
